import ezdxf, glob, math

drawings = sorted(glob.glob('/filesystem/electrical__lv_cable_sizing__blind/project/drawings/*.dxf'))

def get_length(e):
    dxftype = e.dxftype()
    if dxftype == 'LINE':
        p1 = e.dxf.start
        p2 = e.dxf.end
        return math.hypot(p2.x - p1.x, p2.y - p1.y)
    elif dxftype == 'LWPOLYLINE':
        pts = e.get_points('xy')
        length = 0
        for i in range(len(pts) - 1):
            length += math.hypot(pts[i+1][0] - pts[i][0], pts[i+1][1] - pts[i][1])
        if e.closed:
            length += math.hypot(pts[0][0] - pts[-1][0], pts[0][1] - pts[-1][1])
        return length
    elif dxftype == 'POLYLINE':
        pts = [v.dxf.location for v in e.vertices]
        length = 0
        for i in range(len(pts) - 1):
            length += math.hypot(pts[i+1].x - pts[i].x, pts[i+1].y - pts[i].y)
        if e.is_closed:
            length += math.hypot(pts[0].x - pts[-1].x, pts[0].y - pts[-1].y)
        return length
    return 0

circuit_lengths = {}

for path in drawings:
    doc = ezdxf.readfile(path)
    msp = doc.modelspace()
    for e in msp:
        layer = e.dxf.layer
        if layer.startswith('E-RTE-'):
            c = layer.replace('E-RTE-', '')
            l = get_length(e)
            circuit_lengths.setdefault(c, []).append((path.split('/')[-1], e.dxftype(), l))

for c in sorted(circuit_lengths.keys()):
    tot = sum(x[2] for x in circuit_lengths[c])
    print(f'{c}: total horiz = {tot:.2f} ft, details = {circuit_lengths[c]}')
